#!/usr/bin/env python3
"""Render devices/<device>/partition-map.md from partition-map.json (--check for CI)."""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

ORDER = {"never-modify": 0, "blocked-until-verified": 1, "explicit-authorization": 2,
         "explicit-destructive-authorization": 3}


def render(mapping: dict) -> str:
    evidence = mapping["evidence"]
    lines = ["# SM-J260M partition map (generated; do not edit)", "",
             "Generated by `tooling/render_partition_map.py` from `partition-map.json`.",
             f"Source: raw capture `{evidence['raw_capture']}` ({evidence['date']}), controller "
             f"`{evidence['controller']}`.", "",
             "Roles are inferred from partition names only. The policy column is enforced by "
             "`tooling/flash_guard.py`; unlisted targets are denied.", "",
             "| Partition | Device | Size (KiB) | Policy | Role |", "|---|---|---:|---|---|"]
    rows = list(mapping["partitions"].items()) + list(mapping["emmc_special"].items())
    for name, entry in rows:
        lines.append(f"| {name} | {entry['device']} | {entry['bytes'] // 1024} | "
                     f"{entry['write_policy']} | {entry['role']} |")
    lines += ["", "## Policy levels", ""]
    for level, text in sorted(mapping["policy_levels"].items(), key=lambda item: ORDER[item[0]]):
        lines.append(f"- `{level}`: {text}")
    return "\n".join(lines) + "\n"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--device", type=Path, default=Path("devices/samsung-j2core"))
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    mapping = json.loads((args.device / "partition-map.json").read_text(encoding="utf-8"))
    text = render(mapping)
    target = args.device / "partition-map.md"
    if args.check:
        if not target.exists() or target.read_text(encoding="utf-8") != text:
            print(f"{target} is stale; run tooling/render_partition_map.py", file=sys.stderr)
            return 1
        return 0
    target.write_text(text, encoding="utf-8", newline="\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
